const body = $json.body ?? $json;
if (body.approved !== true) throw new Error('Publicação bloqueada: approved deve ser true');
if (!['promptlab', 'zelovita'].includes(body.brand)) throw new Error('brand canônica inválida');
if (!body.request_id) throw new Error('request_id é obrigatório');
const publicationType = String(body.publication_type || 'draft');
if (!['draft', 'schedule', 'now'].includes(publicationType)) throw new Error('publication_type inválido');
if (publicationType === 'schedule' && Number.isNaN(Date.parse(body.scheduled_at))) throw new Error('scheduled_at inválido');
if (!Array.isArray(body.channels) || body.channels.length === 0) throw new Error('channels é obrigatório');
const platforms = body.channels.map(c => String(c.platform || '').toLowerCase());
if (new Set(platforms).size !== platforms.length) throw new Error('canais duplicados');
if (body.brand === 'zelovita' && Array.isArray(body.risk_flags) && body.risk_flags.includes('health_claim') && body.health_reviewed !== true) {
  throw new Error('ZeloVita: alegação de saúde requer health_reviewed=true');
}
const buildSettings = (channel) => {
  if (channel.platform === 'facebook') return { __type: 'facebook', ...(channel.link_url ? { url: channel.link_url } : {}) };
  if (channel.platform === 'instagram') return { __type: 'instagram', post_type: channel.format === 'story' ? 'story' : 'post', is_trial_reel: false, collaborators: [] };
  if (channel.platform === 'tiktok') {
    const privacy = channel.privacy_level || 'SELF_ONLY';
    if (privacy !== 'SELF_ONLY' && body.tiktok_audit_confirmed !== true) throw new Error('TikTok público requer tiktok_audit_confirmed=true');
    return {
      __type: 'tiktok',
      title: String(channel.title || body.topic || '').slice(0, 90),
      privacy_level: privacy,
      duet: Boolean(channel.duet),
      stitch: Boolean(channel.stitch),
      comment: channel.comment !== false,
      autoAddMusic: channel.auto_add_music === true ? 'yes' : 'no',
      brand_content_toggle: Boolean(channel.brand_content),
      brand_organic_toggle: Boolean(channel.brand_organic),
      video_made_with_ai: Boolean(channel.video_made_with_ai),
      content_posting_method: channel.content_posting_method || (privacy === 'SELF_ONLY' ? 'UPLOAD' : 'DIRECT_POST')
    };
  }
  throw new Error(`plataforma inválida: ${channel.platform}`);
};
const posts = body.channels.map(channel => {
  if (!channel.provider_integration_id) throw new Error(`provider_integration_id ausente para ${channel.platform}`);
  const media = Array.isArray(channel.media) ? channel.media : [];
  if (['instagram', 'tiktok'].includes(channel.platform) && media.length === 0) throw new Error(`mídia obrigatória para ${channel.platform}`);
  for (const item of media) {
    if (!item.id || !item.path) throw new Error(`mídia inválida para ${channel.platform}: id e path são obrigatórios`);
  }
  return {
    integration: { id: channel.provider_integration_id },
    value: [{ content: String(channel.caption || ''), image: media }],
    settings: buildSettings(channel)
  };
});
return [{ json: {
  request_id: body.request_id,
  brand: body.brand,
  publication_type: publicationType,
  postiz_payload: {
    type: publicationType,
    date: publicationType === 'schedule' ? new Date(body.scheduled_at).toISOString() : new Date().toISOString(),
    shortLink: false,
    tags: [],
    posts
  }
} }];

const source = $('Quality Gate e payload Postiz').first().json;
return [{ json: {
  ok: true,
  request_id: source.request_id,
  brand: source.brand,
  publication_type: source.publication_type,
  postiz_result: $json,
  processed_at: new Date().toISOString(),
  warning: source.publication_type === 'draft' ? 'Conteúdo salvo como rascunho; não foi publicado.' : null
} }];
